#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }

    vector<long long> out;
    for (int s = 0; s < n + m - 1; s++) {
        long long from = max(0LL, s - m + 1), to = min((long long) s, n - 1);
        if (s % 2 == 0) {
            for (long long i = to; i >= from; i--) out.push_back(g[i][s - i]);
        } else {
            for (long long i = from; i <= to; i++) out.push_back(g[i][s - i]);
        }
    }
    for (size_t k = 0; k < out.size(); k++) cout << out[k] << (k + 1 < out.size() ? " " : "\n");

    return 0;
}

